      final job = ci[jobName] as YamlMap;
      final steps = job['steps'] as YamlList;
      final mint = steps
          .map((s) => s as YamlMap)
          .firstWhere(
            (s) =>
                s['uses']?.toString().startsWith(
                  'actions/create-github-app-token@',
                ) ??
