    }
    final tagSteps = ci['release-tag']['steps'] as YamlList;
    final tagStep = tagSteps
        .map((s) => s as YamlMap)
        .firstWhere(
          (s) => s['run']?.toString().contains('tag_release.sh') ?? false,
        );
