              '$jobName must mint the fa-release-bot token via '
              'actions/create-github-app-token',
            ),
          );
      expect(
        mint['id']?.toString(),
        'app-token',
        reason:
            '$jobName token step id must be app-token for the wiring below',
      );
      expect(
        mint['with']['app-id']?.toString(),
        equals(r'${{ secrets.RELEASE_APP_ID }}'),
